        free(result.iv);
        free(result.key);
        return result;
    }

    // Copy first 16 bytes of key
    memcpy(result.key, key, 16);

    // Pad the input data
    size_t padded_len;
    unsigned char* padded_data = pad_data(data, data_len, &padded_len);
    if (!padded_data) {
        free(result.iv);
        free(result.key);
        return result;
